import React, { useState } from 'react';
import ErrorCases from '@/components/ErrorCases';
import useSessionState from '@/hooks/useSessionState';
import { Alert, Button, Card, Segmented, Select, Space, Table, Tabs, Tag } from 'antd';
import { Chart, PageHeading, ResourceState, Source, useResource, type ResearchData } from '@/components/Research';
import { MODEL_LABELS, type ModelId, type TaskName } from '@/types/ecg';
import { pct, TASK_LABELS } from '@/design';

export default function Experiments({ initialTask }: { initialTask?: TaskName }) {
  const resource = useResource<ResearchData>('/api/research/summary');
  const [task,setTask]=useSessionState<TaskName>('experiments.task',initialTask || (new URLSearchParams(location.search).get('task') === 'nsvf' ? 'nsvf':'nv'));
  const [model,setModel]=useSessionState<ModelId>('experiments.model','cnn_1d'); const [normalized,setNormalized]=useState(false);
  const [cell,setCell]=useState<{actual:string;predicted:string}>();
  if (!resource.data) return <div className="research-page"><ResourceState {...resource} /></div>;
  const data=resource.data; const taskName=task==='nv'?'N/V':'N/S/V/F'; const labels=TASK_LABELS[task];
  const matrix=data.confusion.filter(r=>r.task===taskName && r.model===model);
  const cells=matrix.map(r=>{ const total=matrix.filter(t=>t.true_class===r.true_class).reduce((s,t)=>s+Number(t.count),0); return [labels.indexOf(r.predicted_class),labels.indexOf(r.true_class),normalized?Number(r.count)/Math.max(1,total):Number(r.count)]; });
  const history=data.histories[task];
  return <div className="research-page"><PageHeading title="AI 模型实验中心" description="比较独立分类任务，追溯历史实验指标与真实训练过程。" />
    <Tabs activeKey={task} onChange={key=>setTask(key as TaskName)} items={[{key:'nv',label:'N / V 二分类'},{key:'nsvf',label:'N / S / V / F 四分类'}]} />
    <Alert type={task==='nv'?'info':'warning'} showIcon title={task==='nv'?'正常类与室性异常心拍识别':'四分类局限：S/F 样本少且跨患者分布集中，表现不稳定'} description="历史 test 指标来自最终核验 CSV。Accuracy、Macro-F1 和类别支持量共同解释模型表现。" />
    <Card title={`${taskName} · 历史 test 性能`} className="spaced-card"><Table rowKey="model" pagination={false} scroll={{x:650}} dataSource={data.metrics.filter(r=>r.task===taskName)} columns={[{title:'模型',dataIndex:'model',render:(id:ModelId)=>MODEL_LABELS[id]},...['accuracy','macro_f1','macro_precision','macro_recall'].map((key,i)=>({title:['Accuracy','Macro-F1','Macro Precision','Macro Recall'][i],dataIndex:key,render:(v:string)=><strong>{pct(v)}</strong>})),{title:'Support',dataIndex:'n_test'}]} /><Source>{data.sources.metrics}</Source></Card>
    <div className="research-grid"><Card title="交互式混淆矩阵"><Space wrap><Select aria-label="混淆矩阵模型" value={model} onChange={setModel} options={Object.entries(MODEL_LABELS).map(([value,label])=>({value,label}))} /><Segmented aria-label="矩阵数值" value={normalized?'ratio':'count'} onChange={v=>setNormalized(v==='ratio')} options={[{label:'真实计数',value:'count'},{label:'行归一化',value:'ratio'}]} /></Space><Chart onClick={e=>setCell({actual:labels[e.value[1]],predicted:labels[e.value[0]]})} label={`${taskName} ${model} 真实标签与预测标签混淆矩阵`} height={340} option={{tooltip:{position:'top',confine:true,formatter:(p:any)=>`真实 ${labels[p.value[1]]} / 预测 ${labels[p.value[0]]}<br/>${normalized?pct(p.value[2]):p.value[2]}`},grid:{left:75,right:30,top:32,bottom:75},xAxis:{type:'category',data:labels,name:'预测标签',nameLocation:'middle',nameGap:28,splitArea:{show:true}},yAxis:{type:'category',data:labels,inverse:true,name:'真实标签',nameGap:16},visualMap:{min:0,max:normalized?1:Math.max(...cells.map(c=>c[2])),orient:'horizontal',left:'center',bottom:0,inRange:{color:['#F0F6FF','#1677FF','#142B49']}},series:[{type:'heatmap',data:cells,label:{show:true,formatter:(p:any)=>normalized?pct(p.value[2]):`${p.value[2]}`},emphasis:{itemStyle:{borderWidth:2,borderColor:'#13C2C2'}}}]}} /><Source>{data.sources.confusion}</Source></Card>
    <Card title={`${MODEL_LABELS[model]} · 各类别指标`}><Table rowKey="class" pagination={false} size="middle" dataSource={data.per_class.filter(r=>r.task===taskName && r.model===model)} columns={[{title:'类别',dataIndex:'class',render:(v:string)=><Tag>{v}</Tag>},{title:'Support',dataIndex:'support'},...['precision','recall','f1'].map(key=>({title:key==='f1'?'F1':key==='recall'?'Recall':'Precision',dataIndex:key,render:pct}))]} /><p className="chart-insight">类别支持量决定指标的解释边界，零 Recall 需要在总分之外单独呈现。</p><Source>{data.sources.per_class}</Source></Card></div>
    <div className="category-controls">{labels.flatMap(actual=>labels.filter(predicted=>predicted!==actual).map(predicted=><Button key={actual+predicted} size="small" onClick={()=>setCell({actual,predicted})}>{actual} → {predicted}</Button>))}</div>
    {cell&&labels.includes(cell.actual)&&labels.includes(cell.predicted)&&<ErrorCases key={`${task}-${model}-${cell.actual}-${cell.predicted}`} task={task} model={model} trueLabel={cell.actual} predictedLabel={cell.predicted}/>}
    <Card title="1D-CNN · 实际训练日志" extra={<Tag color="blue">最佳 Epoch {history.best_epoch}</Tag>}><Chart label="Train Loss Validation Loss Validation Macro-F1 与最佳 Epoch" height={330} option={{legend:{top:0},xAxis:{type:'category',name:'Epoch',data:history.rows.map(r=>r.epoch)},yAxis:[{type:'value',name:'Loss'},{type:'value',name:'Macro-F1',min:0,max:1}],series:['train_loss','val_loss','val_macro_f1'].map((key,i)=>({name:['Train Loss','Validation Loss','Validation Macro-F1'][i],type:'line',showSymbol:false,yAxisIndex:i===2?1:0,itemStyle:{color:['#64748B','#13A2A2','#1677FF'][i]},data:history.rows.map(r=>Number(r[key])),markLine:i===2?{symbol:'none',label:{formatter:'最佳 Epoch'},data:[{xAxis:String(history.best_epoch)}]}:undefined}))}} /><Source>{history.source}</Source><p className="chart-insight">训练曲线按已保存日志原样展示，不从 test 结果倒推训练过程，也不补造缺失指标。</p></Card>
  </div>;
}

